// Statistical tests, describe and gaussianKde against scipy.stats
// (test/fixtures/stat-tests.json, generated by scripts/make_tests_reference.py).
import { describe, test, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { stats, seed, normal } from '../index.js'

const ref = JSON.parse(readFileSync(new URL('./fixtures/stat-tests.json', import.meta.url), 'utf8'))
const close = (a, b, rel, abs = 0) => expect(Math.abs(a - b)).toBeLessThanOrEqual(abs + rel * Math.abs(b))

describe('kstest (one sample, exact p-values)', () => {
    for (const c of ref.kstest) {
        for (const [alternative, [statistic, pvalue]] of Object.entries(c.results)) {
            test(`n = ${c.data.length}, ${alternative}`, () => {
                const res = stats.kstest(c.data, stats.normal(0, 1), { alternative })
                close(res.statistic, statistic, 1e-12, 1e-15)
                // exact for n <= 10000 (scipy's own large-n p-value is an approximation)
                close(res.pvalue, pvalue, c.data.length <= 10000 ? 1e-6 : 1e-3, 1e-15)
            })
        }
    }

    test('accepts a cdf function', () => {
        const xs = [0.1, 0.4, 0.45, 0.8]
        expect(stats.kstest(xs, (x) => x).statistic).toBeCloseTo(stats.kstest(xs, stats.uniform(0, 1)).statistic, 15)
    })

    test('p-values are uniform under the null', () => {
        seed(5)
        const ps = Array.from({ length: 400 }, () => stats.kstest(normal(0, 1, 30), stats.normal(0, 1)).pvalue)
        expect(ps.filter((p) => p < 0.05).length / ps.length).toBeGreaterThan(0.02)
        expect(ps.filter((p) => p < 0.05).length / ps.length).toBeLessThan(0.09)
    })
})

describe('ks2samp (exact)', () => {
    for (const c of ref.ks2samp) {
        test(`n = ${c.x.length}, m = ${c.y.length}`, () => {
            const res = stats.ks2samp(c.x, c.y)
            close(res.statistic, c.statistic, 1e-12)
            close(res.pvalue, c.pvalue, 1e-6, 1e-14)
        })
    }
})

describe('chisquareTest', () => {
    for (const c of ref.chisquare) {
        test(`${c.observed.join(',')}`, () => {
            const res = stats.chisquareTest(c.observed, c.expected, { ddof: c.ddof })
            close(res.statistic, c.statistic, 1e-12)
            close(res.pvalue, c.pvalue, 1e-10)
        })
    }
    test('validation', () => {
        expect(() => stats.chisquareTest([1, 2], [1, 1])).toThrow(/same total/)
        expect(() => stats.chisquareTest([1, 2], [3, 0])).toThrow(/positive/)
    })
})

describe('andersonDarling (normality)', () => {
    for (const c of ref.anderson) {
        test(`n = ${c.data.length}`, () => {
            const res = stats.andersonDarling(c.data)
            close(res.statistic, c.statistic, 1e-10)
            expect(res.criticalValues).toEqual(c.critical)
            expect(res.pvalue).toBeGreaterThanOrEqual(0)
            expect(res.pvalue).toBeLessThanOrEqual(1)
        })
    }
    test('approximate p-value is calibrated under the null', () => {
        seed(9)
        const ps = Array.from({ length: 400 }, () => stats.andersonDarling(normal(0, 1, 50)).pvalue)
        const rate = ps.filter((p) => p < 0.05).length / ps.length
        expect(rate).toBeGreaterThan(0.02)
        expect(rate).toBeLessThan(0.09)
    })
})

describe('describe', () => {
    for (const c of ref.describe) {
        test(`n = ${c.nobs}`, () => {
            const d = stats.describe(c.data)
            expect(d.nobs).toBe(c.nobs)
            expect(d.min).toBe(c.min)
            expect(d.max).toBe(c.max)
            for (const k of ['mean', 'variance', 'skewness', 'kurtosis']) close(d[k], c[k], 1e-11)
            const u = stats.describe(c.data, { bias: false })
            close(u.skewness, c.skewnessUnbiased, 1e-11)
            close(u.kurtosis, c.kurtosisUnbiased, 1e-11)
        })
    }
})

describe('gaussianKde', () => {
    for (const c of ref.kde) {
        test(`bandwidth ${c.bandwidth}`, () => {
            const k = stats.gaussianKde(ref.kdeData, { bandwidth: c.bandwidth })
            close(k.factor, c.factor, 1e-14)
            k.pdf(c.x).forEach((v, i) => close(v, c.pdf[i], 1e-12, 1e-300))
            k.cdf(c.x).forEach((v, i) => close(v, c.cdf[i], 1e-10, 1e-15))
        })
    }
    test('sampling follows the estimate', () => {
        seed(2)
        const k = stats.gaussianKde(ref.kdeData)
        const draws = k.sample(4000)
        expect(stats.kstest(draws, (x) => k.cdf(x)).pvalue).toBeGreaterThan(0.001)
    })
})
